const DEFAULT_WHITE_SKIN = { id: 'white', name: 'Default White', price: 0, colors: ['#ffffff', '#f1f5ff', '#b7c5e3'] };
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
let sets = loadSets();
let tasks = loadTasks();
