$('#code-form').addEventListener('submit', event => { event.preventDefault(); const code = $('#code-input').value.trim().toLowerCase(); if (code !== 'qwerty') { $('#code-error').textContent = 'Invalid code.'; return; } coins += 99999990; unlockAllSkins(); renderCoins(); hideModal('#code-modal'); showToast('CODE ACCEPTED — DEDICATION I–V AND ALL OTHER SKINS UNLOCKED!'); });
