  askTask() { if (!this.taskMode) return; this.paused = true; this.timeSinceQuestion = 0; const task = tasks.find(item => !item.done); this.currentTaskId = task?.id || null; $('#task-level-label').textContent = `LEVEL ${String(this.level).padStart(2, '0')} READY`; $('#task-title').textContent = task ? 'Complete one task to continue.' : 'No unfinished task available.'; $('#task-prompt').textContent = task ? 'Finish one task before launching the next level.' : 'Return to the dashboard to add or reopen a task.'; $('#level-task-text').textContent = task?.text || 'Add a task in Task Mode first.'; $('#complete-level-task').disabled = !task; showModal('#task-modal'); }
  askQuestion(levelUp = false) { if (this.taskMode || (this.paused && !this.launching)) return; this.paused = true; this.timeSinceQuestion = 0; const question = this.set.questions[this.questionIndex % this.set.questions.length]; this.currentQuestion = question; this.questionIndex++; this.questionCount++; $('#question-progress').textContent = `QUESTION ${String(this.questionCount).padStart(2, '0')}${levelUp ? ' • LEVEL UP' : ''}`; $('#question-title').textContent = question.q; $('#answer-input').value = ''; $('#answer-feedback').textContent = ''; showModal('#question-modal'); setTimeout(() => $('#answer-input').focus(), 50); }
